{"command": "cd /workdir && python3 -c "
import json
d = json.load(open('output/analysis_results.json'))
# verify structure keys
assert set(d) == {'eda_results','hypothesis_test_results'}
assert set(d['eda_results']) == {'sales_stats_by_region','unique_product_count'}
for r in ['Region A','Region B','Region C']:
    assert set(d['eda_results']['sales_stats_by_region'][r]) == {'mean_sales','median_sales','std_dev_sales'}
ht = d['hypothesis_test_results']
assert set(ht) == {'hypothesis','assumption_checks','chosen_test','test_justification','t_statistic','u_statistic','p_value','confidence_interval_lower','confidence_interval_upper','conclusion'}
print('JSON valid, structure OK')
print('chosen:', ht['chosen_test'], '| p =', ht['p_value'], '| U =', ht['u_statistic'], '| CI:', ht['confidence_interval_lower'], ht['confidence_interval_upper'])
""}

